package com.easy.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.Arrays;

@Configuration
@EnableWebSecurity
@EnableMethodSecurity(prePostEnabled = true)
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .cors(cors -> cors.configurationSource(corsConfigurationSource()))
            .csrf(csrf -> csrf.disable())
            .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(authz -> authz
                // Public endpoints
                .requestMatchers("/actuator/health", "/actuator/info").permitAll()
                .requestMatchers("/swagger-ui/**", "/v3/api-docs/**").permitAll()
                .requestMatchers("/error").permitAll()
                // API endpoints require authentication
                .requestMatchers("/api/v1/**").authenticated()
                .anyRequest().authenticated()
            );
            // TODO: Add JWT authentication filter
            // .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration configuration = new CorsConfiguration();
        configuration.setAllowedOriginPatterns(Arrays.asList("http://localhost:*", "https://*.yourdomain.com"));
        configuration.setAllowedMethods(Arrays.asList("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
        configuration.setAllowedHeaders(Arrays.asList("*"));
        configuration.setAllowCredentials(true);
        configuration.setMaxAge(3600L);

        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/api/**", configuration);
        return source;
    }
}

package com.easy;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
public class LombokTest {

    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    static class TestDto {
        private String name;
        private Integer age;
        private String email;
    }

    @Test
    public void testLombokAnnotations() {
        // Test @Builder
        TestDto dto1 = TestDto.builder()
                .name("John Doe")
                .age(30)
                .email("john@example.com")
                .build();

        assertNotNull(dto1);
        assertEquals("John Doe", dto1.getName());
        assertEquals(30, dto1.getAge());
        assertEquals("john@example.com", dto1.getEmail());

        // Test @NoArgsConstructor
        TestDto dto2 = new TestDto();
        assertNotNull(dto2);

        // Test @AllArgsConstructor
        TestDto dto3 = new TestDto("Jane Doe", 25, "jane@example.com");
        assertNotNull(dto3);
        assertEquals("Jane Doe", dto3.getName());

        // Test @Data (getters/setters)
        dto2.setName("Bob Smith");
        dto2.setAge(35);
        dto2.setEmail("bob@example.com");

        assertEquals("Bob Smith", dto2.getName());
        assertEquals(35, dto2.getAge());
        assertEquals("bob@example.com", dto2.getEmail());

        // Test toString
        String toString = dto1.toString();
        assertTrue(toString.contains("John Doe"));
        assertTrue(toString.contains("30"));

        // Test equals and hashCode
        TestDto dto4 = TestDto.builder()
                .name("John Doe")
                .age(30)
                .email("john@example.com")
                .build();

        assertEquals(dto1, dto4);
        assertEquals(dto1.hashCode(), dto4.hashCode());
    }
}
